package org.telegram.messenger.tetogram;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.telegram.messenger.tetogram.AppearanceIconPolicy.*;
public class AppearanceIconPolicyTest {
 @Test public void everyCalendarMonthHasCorrectSeason(){for(int m=1;m<=12;m++)assertEquals(m<=2||m==12?Season.WINTER:m<=5?Season.SPRING:m<=8?Season.SUMMER:Season.AUTUMN,season(m));}
 @Test public void automaticAndExplicitChoicesAreDeterministic(){assertEquals("MikugramWinter",alias("Mikugram",Season.AUTO,1));assertEquals("TetogramAutumn",alias("Tetogram",Season.AUTO,11));assertEquals("MikugramSpring",alias("Mikugram",Season.SPRING,12));}
 @Test public void fullMatrixHasEightDistinctLogicalAliases(){Set<String> keys=new HashSet<>();for(String brand:new String[]{"Tetogram","Mikugram"})for(Season s:new Season[]{Season.SPRING,Season.SUMMER,Season.AUTUMN,Season.WINTER})keys.add(alias(brand,s,1));assertEquals(8,keys.size());assertEquals("TetogramSummer",alias("Tetogram",Season.SUMMER,7));assertNull(alias("other",Season.WINTER,1));}
 @Test public void completeArtworkSquareFitsGuaranteedAdaptiveSafeCircle(){double side=SEASONAL_CONTENT_SCALE*72;assertTrue(2*side*side<=66*66);assertEquals(108*(1-2*.285)/72,SEASONAL_CONTENT_SCALE,.00001);assertEquals(SAFE_CONTENT_SCALE,scale(Float.NaN),0);assertEquals(.45f,scale(-1),0);assertEquals(1.1f,scale(10),0);}
 @Test public void monthBoundariesAndLeapDayUseLocalCalendar(){Calendar c=new GregorianCalendar(TimeZone.getTimeZone("UTC"));c.clear();c.set(2024,Calendar.FEBRUARY,29,23,59);assertEquals(Season.WINTER,season(c.get(Calendar.MONTH)+1));c.add(Calendar.MINUTE,1);assertEquals(Season.SPRING,season(c.get(Calendar.MONTH)+1));c.set(2026,Calendar.NOVEMBER,30,23,59);assertEquals("TetogramAutumn",alias("Tetogram",Season.AUTO,c.get(Calendar.MONTH)+1));c.add(Calendar.MINUTE,1);assertEquals("TetogramWinter",alias("Tetogram",Season.AUTO,c.get(Calendar.MONTH)+1));}
 @Test public void manualSeasonsNeverDependOnMonth(){for(String brand:new String[]{"Tetogram","Mikugram"})for(Season s:new Season[]{Season.SPRING,Season.SUMMER,Season.AUTUMN,Season.WINTER}){String expected=alias(brand,s,1);for(int month=1;month<=12;month++)assertEquals(expected,alias(brand,s,month));}}
 @Test public void oldAliasesAreEquivalentWithoutForcedComponentMigration(){assertTrue(sameArtwork("MikuWinterIcon","MikugramWinter"));assertTrue(sameArtwork("TetoAutumnIcon","TetogramAutumn"));assertFalse(sameArtwork("TetoAutumnIcon","TetogramWinter"));assertFalse(sameArtwork("DefaultIcon","TetogramWinter"));assertFalse(sameArtwork("DefaultIcon",null));}
 @Test public void autoChangesOnlySeasonAndKeepsCharacter(){for(int month=1;month<=12;month++){assertTrue(alias("Tetogram",Season.AUTO,month).startsWith("Tetogram"));assertTrue(alias("Mikugram",Season.AUTO,month).startsWith("Mikugram"));}}
 @Test public void sameInstantUsesLocalMonthAcrossTimeZones(){Calendar utc=new GregorianCalendar(TimeZone.getTimeZone("UTC"));utc.clear();utc.set(2026,Calendar.DECEMBER,1,0,30);Calendar east=new GregorianCalendar(TimeZone.getTimeZone("Pacific/Kiritimati")),west=new GregorianCalendar(TimeZone.getTimeZone("Pacific/Honolulu"));east.setTimeInMillis(utc.getTimeInMillis());west.setTimeInMillis(utc.getTimeInMillis());assertEquals("MikugramWinter",alias("Mikugram",Season.AUTO,east.get(Calendar.MONTH)+1));assertEquals("MikugramAutumn",alias("Mikugram",Season.AUTO,west.get(Calendar.MONTH)+1));}
}
